WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_rt_same'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '等距离往返', 'kp-trv-rt-same', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "等距离往返"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "去程和回程走的是同一条路，路程相等，但速度不同导致时间不同。核心是平均速度公式。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“某人上山速度是 4，下山原路返回速度是 6，求上下山全程的平均速度”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式（必背秒杀公式）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "等距离往返的平均速度，绝不是两个速度相加除以2！而是【调和平均数】。"}]}, {"type": "katexBlock", "attrs": {"content": "V_{平均} = \\frac{2 \\times V_1 \\times V_2}{V_1 + V_2}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[确认题目是原路返回 (等距离)] --> B[找出去程速度 V1 和 回程速度 V2]\nB --> C[直接套用调和平均数公式: 2*V1*V2 / (V1+V2)]\nC --> D[得出全程平均速度]\nD --> E[如果要求路程, 用平均速度 × 总时间 ÷ 2]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 汽车从甲地到乙地速度为 40km/h，原路返回速度为 60km/h。求往返一次的平均速度？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别等距离：去程与回程是同一段路。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "带入调和公式：V平 = (2 × 40 × 60) / (40 + 60)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "计算：4800 / 100 = 48 km/h。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：48 km/h。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "简单算术平均陷阱：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "(40+60)/2 = 50。考场上选项A必定是50，这是给没有常识的人准备的坟墓。等距往返，慢的那一半耗费的时间更多，所以整体平均速度一定会【偏向慢的那一个数值】（48偏向40）。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "死记硬背这个公式。只要路程相等（比如前一半路程和后一半路程），都可以无脑套用它求整个过程的平均速度。"}]}]}$$ AS jsonb), NULL, '等距离往返的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "等距离往返"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_rt_same", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
